// Normaliza o inscrito e calcula o fim do evento.
// O payload vem do /api/save-lead da LP (ver README da LP, seção 4).
const itens = [];

for (const item of $input.all()) {
  const b = item.json.body || item.json;

  const nome = String(b.nome || '').trim();
  const partes = nome.split(/\s+/);
  const primeiroNome = partes[0] || 'Inscrito';
  const sobrenome = partes.slice(1).join(' ');

  const inicio = b.evento_inicio || '';
  const duracao = Number(b.evento_duracao_min) || 90;
  const fim = inicio ? new Date(new Date(inicio).getTime() + duracao * 60000).toISOString() : '';

  itens.push({
    json: {
      lead_id: String(b.lead_id || ''),
      nome,
      primeiro_nome: primeiroNome,
      sobrenome,
      email: String(b.email || b.convidar_email || '').toLowerCase().trim(),
      whatsapp: String(b.whatsapp || ''),
      fonte: b.fonte || '[Japão] - Live',
      source_id: b.source_id || 'LIVE_JAPAO',
      slug: b.slug || 'japao-live',
      posicao: b.posicao || '',
      evento_titulo: b.evento_titulo || 'Live: Expedição Japão 2027',
      evento_inicio: inicio,
      evento_fim: fim,
      evento_meet_url: b.evento_meet_url || '',
      comunidade_url: b.comunidade_url || '',
      utm_source: b.utm_source || '',
      utm_medium: b.utm_medium || '',
      utm_campaign: b.utm_campaign || '',
      utm_content: b.utm_content || '',
      gclid: b.gclid || '',
      fbclid: b.fbclid || '',
      data_hora_cadastro: b.data_hora_cadastro || '',
    },
  });
}

return itens;
